import type { Question, AnswerOption, QuestionType } from '@jumbo/shared';

/**
 * Extract text from a user-uploaded PDF file in the browser.
 * Uses coordinate-aware line reconstruction so that text cells
 * (such as question numbers '1.' and question prompts or option letters 'A.' and options)
 * generated by FPDF, Word, or LaTeX are reconstructed as exact visual lines.
 */
export async function extractTextFromPdfFile(file: File): Promise<string> {
  const arrayBuffer = await file.arrayBuffer();

  try {
    const pdfjsLib = await import('pdfjs-dist');
    if (pdfjsLib.GlobalWorkerOptions && !pdfjsLib.GlobalWorkerOptions.workerSrc) {
      pdfjsLib.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${
        pdfjsLib.version || '4.0.379'
      }/build/pdf.worker.min.mjs`;
    }

    const pdf = await ((await pdfjsLib.getDocument({ data: arrayBuffer }).promise) as any);
    let fullText = '';

    for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
      const page = await pdf.getPage(pageNum);
      const textContent = await page.getTextContent();
      const rawItems: any[] = textContent.items || [];

      // Filter non-empty items and record their coordinates
      const validItems: { str: string; x: number; y: number; hasEOL?: boolean }[] = [];
      for (const it of rawItems) {
        if ('str' in it && typeof it.str === 'string' && it.str.trim().length > 0) {
          const transform = it.transform || [];
          validItems.push({
            str: it.str.trim(),
            x: transform[4] ?? 0,
            y: transform[5] ?? 0,
            hasEOL: Boolean(it.hasEOL),
          });
        }
      }

      // Group items into visual lines based on vertical Y position
      const pageLines: string[] = [];
      let currentLineItems: { str: string; x: number }[] = [];
      let lastY: number | null = null;

      for (const item of validItems) {
        // In PDF coordinates, when Y changes by more than 4 points, it's a new line
        if (lastY !== null && Math.abs(item.y - lastY) > 4) {
          if (currentLineItems.length > 0) {
            currentLineItems.sort((a, b) => a.x - b.x);
            pageLines.push(currentLineItems.map((c) => c.str).join(' ').trim());
            currentLineItems = [];
          }
        }

        currentLineItems.push({ str: item.str, x: item.x });
        lastY = item.y;

        if (item.hasEOL) {
          currentLineItems.sort((a, b) => a.x - b.x);
          pageLines.push(currentLineItems.map((c) => c.str).join(' ').trim());
          currentLineItems = [];
          lastY = null;
        }
      }

      if (currentLineItems.length > 0) {
        currentLineItems.sort((a, b) => a.x - b.x);
        pageLines.push(currentLineItems.map((c) => c.str).join(' ').trim());
      }

      fullText += '\n' + pageLines.join('\n');
    }

    if (fullText.trim().length > 20) {
      return fullText;
    }
  } catch (err) {
    console.warn('pdfjs-dist failed, falling back to ASCII extraction:', err);
  }

  return extractAsciiStrings(arrayBuffer);
}

/** Basic ASCII/UTF-8 string extractor for uncompressed PDFs */
function extractAsciiStrings(buffer: ArrayBuffer): string {
  const uint8 = new Uint8Array(buffer);
  let result = '';
  let currentString = '';

  for (let i = 0; i < uint8.length; i++) {
    const code = uint8[i]!;
    if ((code >= 32 && code <= 126) || code === 10 || code === 13 || code === 9) {
      currentString += String.fromCharCode(code);
    } else {
      if (currentString.length >= 4) result += currentString + ' ';
      currentString = '';
    }
  }
  return result;
}

/**
 * Intelligent parser that extracts questions, options, and answers from text.
 * Handles:
 * - FPDF and standard exam formats
 * - Inline options sharing the same line (e.g. 'A. Paris B. London C. Rome')
 * - Trailing document Answer Key tables (e.g. 'Answer Key: 1. C, 2. B, 3. A...')
 * - Inline answer lines ('Answer: B', 'Ans: B', 'Correct: C', 'Key: B')
 * - Direct option marking ('*B. Option', 'B. Option (Correct)', '[x]', '✓')
 * - True/False, Multiple Choice, and Puzzle / Ordering question types
 */
export function parseQuestionsFromRawText(rawText: string): Question[] {
  if (!rawText || !rawText.trim()) return [];

  // ── Step 1: Detect and extract trailing answer key section if present ──────
  const docAnswerKey = new Map<number, string>();
  let mainText = rawText;

  const keySectionMatch = rawText.match(
    /(?:(?:\n|\r\n|^)\s*(?:Answer\s*Key|Answers|Solutions|Keys|Key)\s*:?\s*\n)([\s\S]+)$/i,
  );
  if (keySectionMatch && keySectionMatch[1]) {
    const keyContent = keySectionMatch[1];
    mainText = rawText.slice(0, keySectionMatch.index);
    const itemRe = /(?:Q?(\d+)[\.\:\-\)]\s*\(?([A-Fa-f]|True|False|T|F|\d(?:\s*,\s*\d)*)\)?)/gi;
    let km: RegExpExecArray | null;
    while ((km = itemRe.exec(keyContent)) !== null) {
      if (km[1] && km[2]) {
        docAnswerKey.set(parseInt(km[1], 10), km[2].trim().toUpperCase());
      }
    }
  }

  // ── Step 2: Normalize and split multi-option lines ──────────────────────────
  const lines = mainText.split(/\r?\n/);
  const normalizedLines: string[] = [];

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) continue;

    // Detect if a single line contains multiple options: 'A. ... B. ...' or '(A) ... (B) ...'
    const multiOptRegex = /(?:^|\s+)(?:([A-Fa-f])[\.\)]|\(([A-Fa-f])\)|([1-6])[\.\)]|\(([1-6])\))\s+/g;
    const matches = [...line.matchAll(multiOptRegex)];
    if (matches.length > 1) {
      for (let i = 0; i < matches.length; i++) {
        const start = matches[i]!.index;
        const end = i + 1 < matches.length ? matches[i + 1]!.index : line.length;
        normalizedLines.push(line.slice(start, end).trim());
      }
    } else {
      normalizedLines.push(line);
    }
  }

  const cleanText = normalizedLines.join('\n');

  // ── Step 3: Split into question blocks ─────────────────────────────────────
  // Matches: 1. , 1) , 1 - , 1: , (1) , [1] , Q1: , Question 1: , Item 1: , Problem 1:
  const questionSplitRegex =
    /(?:^|\n+)(?=(?:Q(?:uestion)?\s*#?\d+[:.\-\)]?|\(?\d{1,3}\)?\s*[\.\:\-\)]|\bItem\s+\d+[:.]|\bProblem\s+\d+[:.]))/i;
  const blocks = cleanText.split(questionSplitRegex).map((b) => b.trim()).filter(Boolean);

  const questions: Question[] = [];
  let fallbackIdx = 1;

  for (const block of blocks) {
    const numMatch = block.match(/^(?:Q(?:uestion)?\s*#?|\(?\s*)(\d{1,3})/i);
    const qNum = numMatch && numMatch[1] ? parseInt(numMatch[1], 10) : fallbackIdx;
    const docAnswer = docAnswerKey.get(qNum);

    const parsed = parseSingleBlock(block, qNum, docAnswer);
    if (parsed) {
      questions.push(parsed);
      fallbackIdx++;
    }
  }

  return questions;
}

function parseSingleBlock(
  block: string,
  index: number,
  docAnswer?: string,
): Question | null {
  const lines = block.split('\n').map((l) => l.trim()).filter(Boolean);
  if (lines.length === 0) return null;

  const startsWithQ = /^(?:Q(?:uestion)?\s*#?\d+|\(?\s*\d{1,3}\)?\s*[\.\:\-\)])/i.test(block);

  // Extract question prompt
  let prompt = lines[0]!
    .replace(
      /^(?:Q(?:uestion)?\s*#?\d+[:.\-\)]?|\(?\d{1,3}\)?\s*[\.\:\-\)]|\bItem\s+\d+[:.]|\bProblem\s+\d+[:.])\s*/i,
      '',
    )
    .trim();

  if (!prompt && lines.length > 1) {
    prompt = lines[1]!
      .replace(
        /^(?:Q(?:uestion)?\s*#?\d+[:.\-\)]?|\(?\d{1,3}\)?\s*[\.\:\-\)]|\bItem\s+\d+[:.]|\bProblem\s+\d+[:.])\s*/i,
        '',
      )
      .trim();
  }

  // Answer key detection
  let markedAnswer = docAnswer || '';
  const ansMatch = block.match(
    /(?:Answer|Ans|Key|Correct|Solution)\s*(?:key|option)?\s*[:=\-]\s*\(?([A-Fa-f]|True|False|T|F|\d(?:\s*,\s*\d)*)\)?/i,
  );
  if (ansMatch && ansMatch[1] && !markedAnswer) {
    markedAnswer = ansMatch[1].trim().toUpperCase();
  }

  // Options parsing
  const optionRe =
    /^(?:(?:\(([A-Fa-f])\)|([A-Fa-f])[\.\:\-\)]|\(([1-6])\)|([1-6])[\.\:\-\)])\s*(.*)|(\*|\✓|\[x\]|\[v\])\s*(.*))/i;
  const parsedOptions: { id: string; letter: string; text: string; isCorrect: boolean }[] = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i]!;
    // Skip answer key lines
    if (/^(?:Answer|Ans|Key|Correct|Solution)\s*[:=\-]/i.test(line)) continue;

    const m = line.match(optionRe);
    if (m) {
      const letter = (m[1] || m[2] || '').toUpperCase();
      let text = (m[5] || m[7] || line).trim();
      let isCorrect =
        Boolean(m[6]) ||
        text.startsWith('*') ||
        text.includes('(Correct)') ||
        text.includes('[x]') ||
        text.includes('✓');

      text = text.replace(/^(?:\*|\✓|\[x\])\s*|\s*(?:\(Correct\)|\*|\[x\]|✓)$/gi, '').trim();

      parsedOptions.push({
        id: `opt_${index}_${parsedOptions.length + 1}`,
        letter,
        text,
        isCorrect,
      });
    } else if (parsedOptions.length === 0) {
      // Continuation of multi-line prompt
      prompt += ' ' + line;
    }
  }

  // Determine question type hints
  const isTF =
    /\b(?:true\s*or\s*false|true\s*\/\s*false|t\s*\/\s*f)\b/i.test(block) ||
    (parsedOptions.length === 2 &&
      parsedOptions.some((o) => /true/i.test(o.text)) &&
      parsedOptions.some((o) => /false/i.test(o.text))) ||
    markedAnswer === 'TRUE' ||
    markedAnswer === 'FALSE';

  const isPuzzle = /\b(?:order|arrange|chronological|sequence|rank|sort)\b/i.test(prompt);

  // If this block is just a document title / header before Question 1, skip it
  if (!startsWithQ && parsedOptions.length < 2 && !isTF) {
    return null;
  }

  const qType: QuestionType =
    isPuzzle && parsedOptions.length >= 3
      ? 'puzzle'
      : isTF
        ? 'true_false'
        : 'multiple_choice';

  let finalOptions: AnswerOption[] = [];

  if (qType === 'true_false') {
    const isTrue =
      markedAnswer === 'TRUE' ||
      markedAnswer === 'T' ||
      markedAnswer === 'A' ||
      parsedOptions.find((o) => /true/i.test(o.text) && o.isCorrect) !== undefined;

    finalOptions = [
      { id: `opt_${index}_true`, text: 'True', isCorrect: isTrue },
      { id: `opt_${index}_false`, text: 'False', isCorrect: !isTrue },
    ];
  } else if (parsedOptions.length >= 2) {
    if (markedAnswer && markedAnswer.length === 1 && markedAnswer >= 'A' && markedAnswer <= 'F') {
      const targetIdx = markedAnswer.charCodeAt(0) - 65;
      parsedOptions.forEach((o, idx) => {
        o.isCorrect = o.letter ? o.letter === markedAnswer : idx === targetIdx;
      });
    }

    // Guarantee that at least one option is ticked correct
    if (!parsedOptions.some((o) => o.isCorrect)) {
      parsedOptions[0]!.isCorrect = true;
    }

    finalOptions = parsedOptions.slice(0, 6).map((o, idx) => ({
      id: o.id || `opt_${index}_${idx + 1}`,
      text: o.text || `Option ${idx + 1}`,
      isCorrect: Boolean(o.isCorrect),
    }));
  } else {
    // Fallback options
    finalOptions = [
      { id: `opt_${index}_1`, text: 'Option A', isCorrect: true },
      { id: `opt_${index}_2`, text: 'Option B', isCorrect: false },
      { id: `opt_${index}_3`, text: 'Option C', isCorrect: false },
      { id: `opt_${index}_4`, text: 'Option D', isCorrect: false },
    ];
  }

  return {
    id: `extracted_${index}_${Date.now()}`,
    type: qType,
    text: prompt || `Question ${index}`,
    options: finalOptions,
    timeLimit: 20,
    category: 'Custom & Imported',
    difficulty: 'medium',
    points: 1000,
    correctOrder: qType === 'puzzle' ? finalOptions.map((o) => o.id) : undefined,
  };
}
